const msg = $input.first().json;
const OWNER_ID = 8609472348;

// Handle both messages and callback queries
const fromId = msg.message?.from?.id || msg.callback_query?.from?.id;
const text = msg.message?.text || msg.callback_query?.data || '';
const chatId = msg.message?.chat?.id || msg.callback_query?.message?.chat?.id;
const messageId = msg.message?.message_id || msg.callback_query?.message?.message_id;
const callbackQueryId = msg.callback_query?.id || null;

if (fromId !== OWNER_ID) {
  return [{ json: { authorized: false, chatId, text, fromId } }];
}

return [{ json: { authorized: true, chatId, text, fromId, messageId, callbackQueryId } }];

const { text, chatId, callbackQueryId, messageId } = $input.first().json;
const lower = (text || '').toLowerCase().trim();

let intent = 'create_post'; // DEFAULT — assume post request

// Override only for clear non-post intents
if (lower === '/start' || lower === '/help' || lower === 'help' || lower === 'hi' || lower === 'hello') {
  intent = 'help';
} else if (lower === 'status' || lower === 'report' || lower === '/status') {
  intent = 'status';
} else if (lower.startsWith('approve_') || lower.startsWith('reject_')) {
  intent = 'approval_response';
}

return [{ json: { intent, text, chatId, callbackQueryId, messageId } }];

const response = $input.first().json;
const chatId = $('Detect Intent').first().json.chatId;
const originalText = $('Detect Intent').first().json.text;

let postText = '';
if (response.content && response.content[0]) {
  postText = response.content[0].text.trim();
}

if (!postText) {
  throw new Error('Claude returned empty response');
}

// Store post for potential approval flow
return [{ json: { postText, chatId, originalRequest: originalText } }];

